// Lista todas as Data Tables via query SQL no banco do n8n
// Como a API pública não funciona sem Projects, usamos acesso direto ao banco

const tables = [
  // ADICIONE AQUI MANUALMENTE O NOME DAS SUAS DATA TABLES
  // Exemplo:
  // { tableId: 'sua-table-id-1', tableName: 'MinhaTabela1' },
  // { tableId: 'sua-table-id-2', tableName: 'MinhaTabela2' }
];

if (tables.length === 0) {
  throw new Error('Nenhuma Data Table configurada. Edite o nó Code e adicione suas tabelas manualmente.');
}

return tables.map(t => ({
  json: {
    tableId: t.tableId,
    tableName: t.tableName,
    username: $('Edit Fields - Variaveis').first().json.username,
    token: $('Edit Fields - Variaveis').first().json.token,
    repositorio: $('Edit Fields - Variaveis').first().json.repositorio,
    nome: $('Edit Fields - Variaveis').first().json.nome,
    email: $('Edit Fields - Variaveis').first().json.email
  }
}));

const tableId = $('Code - Listar Tabelas (Manual)').item.json.tableId;
const tableName = $('Code - Listar Tabelas (Manual)').item.json.tableName;
const repositorio = $('Code - Listar Tabelas (Manual)').item.json.repositorio;
const rows = $input.all().map(i => i.json);

const safeName = tableName.replace(/[^a-zA-Z0-9_\-]/g, '_');
const jsonContent = JSON.stringify({ tableName, tableId, totalRows: rows.length, rows }, null, 2);

let csvContent = '';
if (rows.length > 0) {
  const keys = Object.keys(rows[0]);
  csvContent += keys.join(',') + '\n';
  rows.forEach(row => {
    const values = keys.map(k => {
      const v = row[k];
      if (v === null || v === undefined) return '';
      const s = String(v);
      return s.includes(',') || s.includes('"') || s.includes('\n')
        ? '"' + s.replace(/"/g, '""') + '"'
        : s;
    });
    csvContent += values.join(',') + '\n';
  });
} else {
  csvContent = 'vazio\n';
}

return [{
  json: {
    tableId, tableName, safeName, repositorio,
    username: $('Code - Listar Tabelas (Manual)').item.json.username,
    token: $('Code - Listar Tabelas (Manual)').item.json.token,
    nome: $('Code - Listar Tabelas (Manual)').item.json.nome,
    email: $('Code - Listar Tabelas (Manual)').item.json.email,
    jsonContent, csvContent,
    totalRows: rows.length
  }
}]];
